use super::*;
struct Memory(Vec<u8>);impl Buffer for Memory{fn append(&mut self,bytes:&[u8])->io::Result<()>{self.0.extend_from_slice(bytes);Ok(())}fn bytes(&self)->&[u8]{&self.0}}
fn page(source:&[u8],cursor:Option<ByteCursor>,limit:usize)->(Fragment,Vec<u8>){let mut storage=Memory(Vec::new());let mut encoder=Collector::new(&mut storage,cursor,limit,2*1024*1024).unwrap();for chunk in source.chunks(113){encoder.write_all(chunk).unwrap();}let meta=encoder.finish().unwrap();(meta,storage.0)}
#[test]fn byte_fragments_exhaust_single_long_utf8_note_without_raising_transport_body_bound(){let text=serde_json::to_string(&serde_json::json!({"note":"α\\\"\n".repeat(120000)})).unwrap()+"\n";assert!(text.len()>super::super::MAX_OUTPUT);let mut next=None;let mut sequence=Continuity::new(2*1024*1024);let mut collected=Vec::new();let mut count=0;loop{let(meta,bytes)=page(text.as_bytes(),next,MAX_FRAGMENT);assert!(bytes.len()<=MAX_FRAGMENT);assert!(serde_json::to_vec(&bytes).unwrap().len()<super::super::MAX_OUTPUT);next=sequence.accept(meta,&bytes,&mut collected).unwrap();count+=1;if next.is_none(){break}assert!(!sequence.is_complete());assert!(sequence.finish().is_err());}assert!(count>1);sequence.finish().unwrap();assert_eq!(collected,text.as_bytes());assert_eq!(super::super::MAX_OUTPUT,524288);}
#[test]fn byte_continuity_refuses_gaps_changed_output_truncation_duplicate_and_writer_failure(){let source=b"same admitted final encoder output";let(first,bytes)=page(source,None,7);let mut sequence=Continuity::new(1024);let next=sequence.accept(first,&bytes,&mut Vec::new()).unwrap();assert!(sequence.finish().is_err());let mut wrong=first;wrong.offset=14;assert!(sequence.accept(wrong,&bytes,&mut Vec::new()).is_err());assert!(!sequence.is_complete());assert!(sequence.accept(first,&bytes,&mut Vec::new()).is_err());let mut storage=Memory(Vec::new());let mut other=Collector::new(&mut storage,next,7,1024).unwrap();other.write_all(b"different output same source pins").unwrap();assert!(other.finish().is_err());let(mut complete,data)=page(source,None,MAX_FRAGMENT);complete.output_id=OutputId(0);assert!(Continuity::new(1024).accept(complete,&data,&mut Vec::new()).is_err());assert!(Continuity::new(2).accept(first,&bytes,&mut Vec::new()).is_err());struct Broken;impl Write for Broken{fn write(&mut self,_:&[u8])->io::Result<usize>{Err(io::Error::from_raw_os_error(112))}fn flush(&mut self)->io::Result<()>{Ok(())}}let mut failed=Continuity::new(1024);assert_eq!(failed.accept(first,&bytes,&mut Broken).unwrap_err().raw_os_error(),Some(112));assert!(failed.finish().is_err());}

#[test]fn incomplete_or_corrupt_sequence_never_publishes_its_staged_prefix(){let text=b"borrowed final encoded bytes staged until complete";let(first,bytes)=page(text,None,7);let mut receiver=Continuity::new(1024);let mut staging=Vec::new();let next=receiver.accept(first,&bytes,&mut staging).unwrap();assert!(!staging.is_empty());let(mut last,tail)=page(text,next,MAX_FRAGMENT);last.output_id=OutputId(0);assert!(receiver.accept(last,&tail,&mut staging).is_err());let mut published=Vec::new();if receiver.finish().is_ok(){published.write_all(&staging).unwrap();}assert!(published.is_empty(),"a data prefix never grants completed publication");let mut receiver=Continuity::new(1024);let(mut last,tail)=page(text,None,MAX_FRAGMENT);last.total+=1;assert!(receiver.accept(last,&tail,&mut Vec::new()).is_err());assert!(receiver.finish().is_err());}
